#include <cstdio>
#include <cstring>
#include <queue>
#include <algorithm>
using namespace std;

typedef long long LL;

template<int N>
struct Dinic {
    int head[N], tot, cur[N], d[N], u, v, s, t, src, sink;

    struct Edge {
        int v, nxt, cap;
    } E[111111];

    void add(int u, int v, int cap) {
        E[tot] = {v, head[u], cap};
        head[u] = tot++;
        E[tot] = {u, head[v], 0};
        head[v] = tot++;
    }

    void init() {
        memset(head, -1, sizeof head);
        tot = 0;
    }

    bool bfs() {
        memset(d, -1, sizeof d);
        memcpy(cur, head, sizeof head);
        d[src] = 0;
        queue<int> Q;
        Q.push(src);
        while (!Q.empty()) {
            u = Q.front(); Q.pop();
            for (int i = head[u]; ~i; i = E[i].nxt) {
                v = E[i].v;
                if (d[v] == -1 && E[i].cap) {
                    d[v] = d[u] + 1;
                    Q.push(v);
                }
            }
        }
        return d[sink] != -1;
    }

    int dfs(int u, int in) {
        if (u == sink) return in;
        int flow = 0, f;
        for (int &i = cur[u]; ~i; i = E[i].nxt) {
            v = E[i].v;
            if (d[v] == d[u] + 1 && E[i].cap) {
                f = dfs(v, min(in - flow, E[i].cap));
                if (f) {
                    flow += f;
                    E[i].cap -= f;
                    E[i ^ 1].cap += f;
                    if (flow == in) break;
                }
            }
        }
        if (flow < in) d[u] = -1;
        return flow;
    }

    const int inf = 1e9;
    int dinic(int _src, int _sink) {
        src = _src, sink = _sink;
        int flow = 0;
        while (bfs())
            flow += dfs(src, inf);
        return flow;
    }
};

int n;
const int N = 15;
char field[N][N], capsule[N][N];
int Z[N][N], S[N][N];
int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};

inline bool In(int i, int j) {
    return i >= 0 && i < n && j >= 0 && j < n;
}

Dinic<210> F;
int t;
const int inf = 1e9;

inline bool isdigit(char ch) {
    return ch >= '1' && ch <= '9';
}

void bfs(int x, int y, int d[][N], bool f) {
    int sx = x, sy = y;
    fill(d[0], d[N], inf);
    d[x][y] = 0;
    queue<int> Q;
    Q.push(x);
    Q.push(y);
    if (f && isdigit(capsule[x][y])) {
        F.add(sx * n + sy, sx * n + sy + n * n, inf);
    }
    while (!Q.empty()) {
        x = Q.front(); Q.pop();
        y = Q.front(); Q.pop();
        if (d[x][y] == t) break;
        for (int o = 0; o < 4; ++o) {
            int xx = x + dx[o];
            int yy = y + dy[o];
            if (In(xx, yy) && d[xx][yy] == inf && capsule[xx][yy] != 'Y') {
                if (Z[xx][yy] > d[x][y] + 1 || (Z[xx][yy] == d[x][y] + 1 && isdigit(capsule[xx][yy]))) {
                    d[xx][yy] = d[x][y] + 1;
                    if (f && isdigit(capsule[xx][yy])) {
                        F.add(sx * n + sy, xx * n + yy + n * n, inf);
                    }
                    if (Z[xx][yy] > d[x][y] + 1 || !f) {
                        Q.push(xx);
                        Q.push(yy);
                    }
                }
            }
        }
    }
}

int main() {
    int x, y;
    scanf("%d%d", &n, &t);
    int src = n * n * 2, sink = src + 1;
    F.init();
    for (int i = 0; i < n; ++i) {
        scanf("%s", field[i]);
        for (int j = 0; j < n; ++j) {
            if (field[i][j] == 'Z') {
                x = i, y = j;
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        scanf("%s", capsule[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(capsule[i][j])) {
                F.add(i * n + j + n * n, sink, capsule[i][j] - '0');
            }
        }
    }
    bfs(x, y, Z, false);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(field[i][j])) {
                F.add(src, i * n + j, field[i][j] - '0');
                bfs(i, j, S, true);
            }
        }
    }
    printf("%d\n", F.dinic(src, sink));
    return 0;
}
